using System.Reflection;
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.Pricing;

public sealed class GoldDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysApproved95()
    {
        var checkoutTypes = new[] { typeof(ApplicationMarker).Assembly, typeof(DomainMarker).Assembly }
            .SelectMany(a => a.GetTypes())
            .Where(t => t.IsPublic && t.Name.Contains("Checkout", StringComparison.OrdinalIgnoreCase)
                        || t.Name.Contains("Pricing", StringComparison.OrdinalIgnoreCase) && t.Name.EndsWith("Calculator"))
            .ToList();

        Assert.True(checkoutTypes.Count > 0, "No checkout/pricing capability exists, so the payable total of 95.00 cannot be produced.");
    }
}
